from pathlib import Path
p=Path('tests/simulation.test.ts')
s=p.read_text()
old="""  it('persists settings separately and rejects out-of-range values', () => {\n    const settings = { ...DEFAULT_SETTINGS, sensitivity: 1.4, fov: 90, masterVolume: 0.3, effectsVolume: 0.6, quality: 'low' as const };\n    saveSettings(settings);\n    expect(loadSettings()).toMatchObject(settings);\n    expect(loadSettings()).toMatchObject({viewmodelFov:50,invertY:false,headBob:false,renderScale:1,shadows:true,crosshairOpacity:1,showCompass:true});\n    expect(hasSave()).toBe(false);\n    localStorage.setItem(SAVE.SETTINGS_KEY, JSON.stringify({ sensitivity: -10, fov: 300, quality: 'ultra', effectsVolume: 0.2 }));\n    expect(loadSettings()).toMatchObject({ sensitivity: 1, fov: DEFAULT_SETTINGS.fov, quality: 'high', effectsVolume: 0.2 });\n  });"""
new="""  it('persists expanded settings separately, migrates legacy sensitivity and rejects invalid values', () => {\n    const settings = { ...DEFAULT_SETTINGS, keybinds:{...DEFAULT_SETTINGS.keybinds,forward:'KeyP'}, language:'cs' as const, sensitivityX:1.4, sensitivityY:.8, fov:90, masterVolume:.3, musicVolume:.25, effectsVolume:.6, ambientVolume:.4, quality:'ultra' as const };\n    saveSettings(settings);\n    expect(loadSettings()).toMatchObject(settings);\n    expect(loadSettings()).toMatchObject({viewmodelFov:50,invertY:false,headBob:false,cameraShake:true,motionBlur:false,renderScale:1,shadows:true,crosshairOpacity:1,showCompass:true});\n    expect(hasSave()).toBe(false);\n    localStorage.setItem(SAVE.SETTINGS_KEY, JSON.stringify({ sensitivity:1.35, sensitivityX:-10, sensitivityY:99, fov:300, quality:'impossible', effectsVolume:.2, language:'xx', keybinds:{forward:'KeyZ'} }));\n    expect(loadSettings()).toMatchObject({ language:'en', sensitivityX:1.35, sensitivityY:1.35, fov:DEFAULT_SETTINGS.fov, quality:'high', effectsVolume:.2, keybinds:{forward:'KeyZ'} });\n  });"""
if old not in s: raise SystemExit('legacy settings test marker not found')
p.write_text(s.replace(old,new,1))
print('v0.3.0 settings tests updated')
